'use strict';

/* eslint max-nested-callbacks: ["error", 5] -- Nested reference layout matrices and synchronous tape rejection assertions. */

// MODULES //

var DataView = require( '@stdlib/array/dataview' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Float64Array = require( '@stdlib/array/float64' );
var min = require( '@stdlib/math/base/special/min' );
var max = require( '@stdlib/math/base/special/max' );
var abs = require( '@stdlib/math/base/special/abs' );
var cases = require( './fixtures/reference.json' ).cases;


// VARIABLES //

var view = new DataView(new ArrayBuffer(8));


// FUNCTIONS //

/**
* Decodes exact reference bits.
* @private
* @param {string} hex - IEEE bits
* @returns {number} value
*/
function decode(hex) {
	view.setUint32(0, parseInt(hex.slice(0, 8), 16));
	view.setUint32(4, parseInt(hex.slice(8), 16));
	return view.getFloat64(0);
}
/**
* Encodes exact result bits including zero signs.
* @private
* @param {number} x - number
* @returns {string} exact bits
*/
function bits(x) {
	view.setFloat64(0, x);
	return (('00000000' + view.getUint32(0).toString(16)).slice(-8) + ('00000000' + view.getUint32(4).toString(16)).slice(-8));
}
/**
* Maps current numeric storage to exact bits.
* @private
* @param {Float64Array} x - storage
* @returns {StringArray} bits
*/
function snapshot(x) {
	return Array.prototype.map.call(x, bits);
}
/**
* Constructs an injective padded band and output vector.
* @private
* @param {PositiveInteger} h - height
* @param {PositiveInteger} n - columns
* @param {integer} r - row stride
* @param {integer} c - column stride
* @returns {Object} current signed view
*/
function geometry(h, n, r, c) {
	var high;
	var low;
	var dr;
	var dc;
	dr = ((h - 1) * r);
	dc = ((n - 1) * c);
	low = (min(0, dr) + min(0, dc));
	high = (max(0, dr) + max(0, dc));
	return {
		'o': (3 - low),
		'len': ((7 + high) - low)
	};
}
/**
* Runs actual finite reference, layout and guard regression coverage.
* @private
* @param {Object} t - tape assertion context
* @param {Function} f - public routine
* @returns {void}
*/
function run(t, f) {
	cases.forEach(function each(x) {
		[
			121,
			122
		].forEach(function triangle(u) {
			[
				0,
				2,
				8
			].forEach(function bandwidth(kd) {
				[
					'column',
					'row',
					'negative',
					'mixed'
				].forEach(function layout(mode) {
					var beforeA;
					var beforeS;
					var beforeC;
					var beforeM;
					var result;
					var order;
					var slots;
					var diag;
					var lda;
					var ss;
					var ag;
					var sg;
					var ab;
					var sb;
					var sc;
					var am;
					var oc;
					var om;
					var n;
					var h;
					var r;
					var c;
					var a;
					var s;
					var j;
					diag = x.diag.map(decode);
					n = diag.length;
					h = (kd + 1);
					slots = [];
					if ((mode === 'column')) {
						r = 1;
						c = (h + 2);
						ss = 1;
						lda = c;
						order = 102;
					} else if ((mode === 'row')) {
						r = (n + 2);
						c = 1;
						ss = 1;
						lda = r;
						order = 101;
					} else if ((mode === 'negative')) {
						r = -2;
						c = -((2 * h) + 3);
						ss = -2;
					} else {
						r = -2;
						c = ((2 * h) + 3);
						ss = -3;
					}
					ag = geometry(h, n, r, c);
					sg = geometry(n, 1, ss, 0);
					if (order) {
						ag.o = 0;
						sg.o = 0;
					}
					ab = new Float64Array((ag.len + 4));
					sb = new Float64Array((sg.len + 4));
					ab.fill(Infinity);
					sb.fill(-222);
					a = new Float64Array(ab.buffer, 16, ag.len);
					s = new Float64Array(sb.buffer, 16, sg.len);
					sc = new Float64Array(7);
					am = new Float64Array(8);
					sc.fill(-987654.125);
					am.fill(-333);
					oc = ( order ) ? 0 : 3;
					om = ( order ) ? 0 : 5;
					for (j = 0; (j < n); j++) {
						a[((ag.o + ((u === 121) ? (kd * r) : 0)) + (j * c))] = diag[j];
						slots.push(((sg.o + (j * ss)) + 2));
					}
					beforeA = snapshot(ab);
					beforeS = snapshot(sb);
					beforeC = snapshot(sc);
					beforeM = snapshot(am);
					result = ( order ) ? f(order, u, n, kd, a, lda, s, sc, am) : f.ndarray(u, n, kd, a, r, c, ag.o, s, ss, sg.o, sc, oc, am, om);
					t.strictEqual(result, x.expected.INFO, ((x.id + ' INFO ') + mode));
					for (j = 0; (j < n); j++) {
						t.strictEqual(bits(s[(sg.o + (j * ss))]), x.expected.S[j].hex, (x.id + ' output bits'));
						if ((result === 0)) {
							t.ok((abs((((diag[j] * s[(sg.o + (j * ss))]) * s[(sg.o + (j * ss))]) - 1)) <= (8 * 2.220446049250313e-16)), 'independent scaled diagonal near one');
						}
					}
					t.strictEqual(bits(sc[oc]), x.expected.SCOND.hex, 'complete scalar sentinel/output');
					t.strictEqual(bits(am[om]), x.expected.AMAX.hex, 'full-column AMAX');
					t.deepEqual(snapshot(ab), beforeA, 'input and unused band bits untouched');
					t.deepEqual(snapshot(sb).filter(function guard(v, idx) {
						return (slots.indexOf(idx) < 0);
					}), beforeS.filter(function guard(v, idx) {
						return (slots.indexOf(idx) < 0);
					}), 'output padding untouched');
					beforeC[oc] = bits(sc[oc]);
					beforeM[om] = bits(am[om]);
					t.deepEqual(snapshot(sc), beforeC, 'only active SCOND scalar written');
					t.deepEqual(snapshot(am), beforeM, 'only active AMAX scalar written');
				});
			});
		});
	});
}


// EXPORTS //

module.exports = {
	'run': run,
	'bits': bits,
	'decode': decode,
	'snapshot': snapshot
};
